from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField
from taf.gnb.oam.coam.vdu.schemas.trs.certificates_info import CertificatesInfo, Details


class DetailsTRSV2(Details):
    key_pool_type = SchemaField(name='key_pool_type', optional=True)

    def __init__(self, issued_to, issued_by, valid_from, valid_to, serial_number, ca_type, key_pool_type):
        self.key_pool_type = key_pool_type
        super(DetailsTRSV2, self).__init__(issued_to, issued_by, valid_from, valid_to, serial_number, ca_type)


class CertificatesInfoTRSV2(CertificatesInfo):
    details = SchemaField(name='details', klass=DetailsTRSV2, not_null=True)

    def __init__(self, id, type, details):
        self.details = details
        super(CertificatesInfoTRSV2, self).__init__(id, type, details)
